import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';

import { postIdempotent } from './http-idempotency';
import { RuntimeConfigService } from './runtime-config.service';

// Wire format for Duration/TotalDuration matches the backend's default System.Text.Json TimeSpan
// serialization (the "c" format: "[-][d.]hh:mm:ss[.fffffff]" -- see SubtaskResponse.Duration /
// TaskTemplateResponse.TotalDuration in CreateTaskTemplate.Endpoint.cs). The service converts to
// and from whole minutes at this boundary so components never touch the wire string directly.
function parseDurationMinutes(duration: string): number {
  const match = /^-?(?:(\d+)\.)?(\d+):(\d+):(\d+)/.exec(duration);

  if (!match) {
    return 0;
  }

  const [, days, hours, minutes] = match;
  return (Number(days ?? 0) * 24 + Number(hours)) * 60 + Number(minutes);
}

function formatDurationMinutes(totalMinutes: number): string {
  const wholeMinutes = Math.max(0, Math.round(totalMinutes));
  const hours = Math.floor(wholeMinutes / 60);
  const minutes = wholeMinutes % 60;
  return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:00`;
}

export interface Subtask {
  id: string;
  title: string;
  icon: string | null;
  durationMinutes: number;
}

// A TaskTemplate belongs to exactly one child -- it's scoped by childId in the URL because that's
// whose library it is. No group-sharing axis (TaskLibraryAccessTier has no analog to
// MealplanAccessTier's group scope).
export interface TaskTemplate {
  id: string;
  name: string;
  icon: string;
  color: string;
  subtasks: Subtask[];
  totalDurationMinutes: number;
  isArchived: boolean;
  createdBy: string;
  lastModifiedBy: string;
}

export interface TaskTemplateDetails {
  name: string;
  icon: string;
  color: string;
}

interface SubtaskResponse {
  id: string;
  title: string;
  icon: string | null;
  duration: string;
}

interface TaskTemplateResponse {
  id: string;
  name: string;
  icon: string;
  color: string;
  subtasks: SubtaskResponse[];
  totalDuration: string;
  isArchived: boolean;
  createdBy: string;
  lastModifiedBy: string;
}

function fromResponse(response: TaskTemplateResponse): TaskTemplate {
  return {
    id: response.id,
    name: response.name,
    icon: response.icon,
    color: response.color,
    subtasks: response.subtasks.map((subtask) => ({
      id: subtask.id,
      title: subtask.title,
      icon: subtask.icon,
      durationMinutes: parseDurationMinutes(subtask.duration)
    })),
    totalDurationMinutes: parseDurationMinutes(response.totalDuration),
    isArchived: response.isArchived,
    createdBy: response.createdBy,
    lastModifiedBy: response.lastModifiedBy
  };
}

function totalDurationMinutesOf(subtasks: Subtask[]): number {
  return subtasks.reduce((sum, subtask) => sum + subtask.durationMinutes, 0);
}

@Injectable({ providedIn: 'root' })
export class TaskLibraryService {
  private readonly http = inject(HttpClient);
  private readonly runtimeConfig = inject(RuntimeConfigService);

  // Shared across every component reading `templates` (e.g. the task-library editor and a
  // template picker on the same page), so a create/update/archive/subtask-edit in one place is
  // reflected everywhere else immediately, without each component needing to know about the
  // others -- mirrors MealplansService.meals.
  private readonly templatesState = signal<TaskTemplate[]>([]);
  readonly templates = this.templatesState.asReadonly();

  private base(): string {
    return `${this.runtimeConfig.apiBaseUrl}/task-templates`;
  }

  private replaceTemplate(template: TaskTemplate): void {
    this.templatesState.update((current) => current.map((existing) => (existing.id === template.id ? template : existing)));
  }

  // Used when the caller stops pointing at any particular child (e.g. a calendar assignee that
  // isn't one of the guardian's children) -- there's no valid childId to list templates for, so
  // the shared state should reflect "nothing selected" rather than keep showing the last child's
  // templates.
  clearTemplates(): void {
    this.templatesState.set([]);
  }

  async listTaskTemplates(childId: string): Promise<TaskTemplate[]> {
    const responses = await firstValueFrom(this.http.get<TaskTemplateResponse[]>(`${this.base()}/children/${childId}`));
    const templates = responses.map(fromResponse);
    this.templatesState.set(templates);
    return templates;
  }

  async createTaskTemplate(childId: string, request: TaskTemplateDetails): Promise<TaskTemplate> {
    const response = await firstValueFrom(
      postIdempotent<TaskTemplateResponse>(this.http, `${this.base()}/children/${childId}`, request)
    );
    const template = fromResponse(response);
    this.templatesState.update((current) => [...current, template]);
    return template;
  }

  async updateTaskTemplate(templateId: string, request: TaskTemplateDetails): Promise<TaskTemplate> {
    const response = await firstValueFrom(this.http.patch<TaskTemplateResponse>(`${this.base()}/${templateId}`, request));
    const template = fromResponse(response);
    this.replaceTemplate(template);
    return template;
  }

  async archiveTaskTemplate(templateId: string): Promise<void> {
    await firstValueFrom(this.http.delete<void>(`${this.base()}/${templateId}`));
    this.templatesState.update((current) =>
      current.map((template) => (template.id === templateId ? { ...template, isArchived: true } : template))
    );
  }

  async addSubtask(templateId: string, title: string, icon: string | null, durationMinutes: number, position?: number | null): Promise<TaskTemplate> {
    const response = await firstValueFrom(
      postIdempotent<TaskTemplateResponse>(this.http, `${this.base()}/${templateId}/subtasks`, {
        title,
        icon,
        duration: formatDurationMinutes(durationMinutes),
        position: position ?? null
      })
    );
    const template = fromResponse(response);
    this.replaceTemplate(template);
    return template;
  }

  async updateSubtask(templateId: string, subtaskId: string, title: string, icon: string | null, durationMinutes: number): Promise<TaskTemplate> {
    const response = await firstValueFrom(
      this.http.patch<TaskTemplateResponse>(`${this.base()}/${templateId}/subtasks/${subtaskId}`, {
        title,
        icon,
        duration: formatDurationMinutes(durationMinutes)
      })
    );
    const template = fromResponse(response);
    this.replaceTemplate(template);
    return template;
  }

  async removeSubtask(templateId: string, subtaskId: string): Promise<void> {
    await firstValueFrom(this.http.delete<void>(`${this.base()}/${templateId}/subtasks/${subtaskId}`));
    this.templatesState.update((current) =>
      current.map((template) => {
        if (template.id !== templateId) {
          return template;
        }

        const subtasks = template.subtasks.filter((subtask) => subtask.id !== subtaskId);
        return { ...template, subtasks, totalDurationMinutes: totalDurationMinutesOf(subtasks) };
      })
    );
  }

  async reorderSubtasks(templateId: string, newOrder: string[]): Promise<TaskTemplate> {
    const response = await firstValueFrom(this.http.put<TaskTemplateResponse>(`${this.base()}/${templateId}/subtasks/order`, { newOrder }));
    const template = fromResponse(response);
    this.replaceTemplate(template);
    return template;
  }
}

src/app/core/task-run.ts.source:
import { CalendarOccurrence } from './calendars.service';

// A "run" is every subtask occurrence a single ScheduleTaskFromTemplate-created CalendarItem
// produces for one calendar day -- e.g. a 3-subtask morning routine template shows up as 3
// CalendarItemOccurrence rows sharing the same itemId (and parentTitle, the template-scheduled
// item's own Title), one per subtask. Rendered separately, that reads as three unrelated events;
// TaskRun exists purely to group them back into one visual block. Grouping is a rendering
// concern only -- it never changes how completion is tracked or targeted (see occurrenceKey
// below), and the ungrouped occurrence array from the backend remains the single source of truth.
export interface TaskRun {
  itemId: string;
  parentTitle: string;
  calendarId: string;
  calendarName: string;
  color: string;
  icon: string;
  subtasks: CalendarOccurrence[];
}

// One row in a grouped agenda: either a run of subtask occurrences, or any other occurrence
// (an event, or a plain hand-entered task) passed through unchanged.
export type AgendaEntry = CalendarOccurrence | TaskRun;

export function isTaskRun(entry: AgendaEntry): entry is TaskRun {
  return Array.isArray((entry as TaskRun).subtasks);
}

// The date portion of whichever instant the occurrence is anchored on. Both startsAt and dueAt
// are full ISO instants ("...T09:00:00Z") whose first 10 characters are always the calendar date
// they're stored against -- slicing is enough here, no timezone conversion needed, since this is
// only used to keep two occurrences of the same *recurring* template-scheduled item (same itemId,
// different calendar day) from being folded into a single run.
function dateKeyOf(occurrence: Pick<CalendarOccurrence, 'startsAt' | 'dueAt'>): string {
  return (occurrence.startsAt ?? occurrence.dueAt ?? '').slice(0, 10);
}

// Groups a list of occurrences (typically one calendar day's worth, already the caller's unit of
// display) into agenda rows. An occurrence with a non-null parentTitle is one subtask of a
// template-scheduled task -- every such occurrence sharing an itemId and calendar day folds into
// a single TaskRun, in encounter order, at the position its first subtask appeared. Every other
// occurrence (an event, or a plain hand-entered task -- parentTitle null) passes through
// unchanged, preserving today's one-row-per-occurrence rendering exactly.
export function groupTaskRuns(occurrences: CalendarOccurrence[]): AgendaEntry[] {
  const entries: AgendaEntry[] = [];
  const runsByKey = new Map<string, TaskRun>();

  for (const occurrence of occurrences) {
    if (!occurrence.parentTitle) {
      entries.push(occurrence);
      continue;
    }

    const key = `${occurrence.itemId}|${dateKeyOf(occurrence)}`;
    let run = runsByKey.get(key);

    if (!run) {
      run = {
        itemId: occurrence.itemId,
        parentTitle: occurrence.parentTitle,
        calendarId: occurrence.calendarId,
        calendarName: occurrence.calendarName,
        color: occurrence.color,
        // The parent's own effective icon, not the (possibly subtask-specific) icon of whichever
        // subtask happens to appear first -- see CalendarItemOccurrence.parentIcon.
        icon: occurrence.parentIcon ?? occurrence.icon,
        subtasks: []
      };
      runsByKey.set(key, run);
      entries.push(run);
    }

    run.subtasks.push(occurrence);
  }

  return entries;
}

// Stable per-toggle key for a task occurrence. Two subtask occurrences of the same
// template-scheduled run share an itemId but never a subtaskId, so keying on itemId alone (as
// every "is this task currently being toggled/completed" signal did before subtask occurrences
// existed) makes completing one subtask visually toggle every sibling subtask sharing that
// itemId -- this is the fix for that. subtaskId is undefined/null for a plain (non-template) task,
// so its key reduces to `${itemId}:`, distinct per itemId exactly as before.
//
// The date suffix (via dateKeyOf) matters once a caller's in-memory occurrence array can span more
// than one calendar day -- a week/workweek view, for instance. Without it, a recurring item's
// itemId (and, for a plain recurring task, empty subtaskId) repeats once per day it occurs, so the
// optimistic "mark done" update below -- which patches every occurrence whose key matches -- would
// flip every day's occurrence of that item at once instead of just the one that was toggled.
export function occurrenceKey(occurrence: Pick<CalendarOccurrence, 'itemId' | 'subtaskId' | 'startsAt' | 'dueAt'>): string {
  return `${occurrence.itemId}:${occurrence.subtaskId ?? ''}:${dateKeyOf(occurrence)}`;
}

